const express = require('express');
const crypto = require('crypto');
const http = require('http');

const app = express();
app.use(express.json());

const SECRET = process.env.HMAC_SECRET || crypto.randomBytes(32).toString('hex');
const NONCE_EXPIRY_MS = 300000; // 5 minutes

// In-memory nonce store with expiration tracking
class NonceStore {
  constructor() {
    this.seen = new Map();
    this.draining = false;
    this._cleanupInterval = setInterval(() => this.cleanup(), 60000);
  }

  cleanup() {
    const now = Date.now();
    for (const [nonce, timestamp] of this.seen.entries()) {
      if (now - timestamp > NONCE_EXPIRY_MS) {
        this.seen.delete(nonce);
      }
    }
  }

  markUsed(nonce) {
    if (this.draining) {
      // During graceful shutdown, we still accept requests in flight
      // but skip nonce recording to avoid memory growth during drain
      return true;
    }
    if (this.seen.has(nonce)) {
      return false;
    }
    this.seen.set(nonce, Date.now());
    return true;
  }

  hasBeenUsed(nonce) {
    return this.seen.has(nonce);
  }

  startDraining() {
    this.draining = true;
    clearInterval(this._cleanupInterval);
  }
}

const nonceStore = new NonceStore();

function verifySignature(payload, signature, nonce, timestamp) {
  const now = Date.now();
  const requestTime = parseInt(timestamp, 10);

  // Reject requests older than 5 minutes
  if (isNaN(requestTime) || Math.abs(now - requestTime) > NONCE_EXPIRY_MS) {
    return { valid: false, reason: 'timestamp_expired' };
  }

  // Compute expected signature
  const message = `${timestamp}.${nonce}.${JSON.stringify(payload)}`;
  const expected = crypto.createHmac('sha256', SECRET)
    .update(message)
    .digest('hex');

  // Constant-time comparison
  if (!crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expected, 'hex'))) {
    return { valid: false, reason: 'invalid_signature' };
  }

  // Check and record nonce
  if (!nonceStore.markUsed(nonce)) {
    return { valid: false, reason: 'nonce_reused' };
  }

  return { valid: true };
}

// Protected endpoint for fund transfers
app.post('/api/transfer', (req, res) => {
  const { payload, signature, nonce, timestamp } = req.body;

  if (!payload || !signature || !nonce || !timestamp) {
    return res.status(400).json({ error: 'missing_fields' });
  }

  const result = verifySignature(payload, signature, nonce, timestamp);
  if (!result.valid) {
    return res.status(403).json({ error: result.reason });
  }

  // Process the transfer
  const { from, to, amount } = payload;
  console.log(`Transfer: ${from} -> ${to}: $${amount}`);

  return res.status(200).json({ success: true, transfer: { from, to, amount } });
});

app.get('/health', (req, res) => {
  res.json({ status: nonceStore.draining ? 'draining' : 'healthy' });
});

const server = http.createServer(app);
const PORT = process.env.PORT || 3000;

server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

// Graceful shutdown handling
function gracefulShutdown(signal) {
  console.log(`Received ${signal}. Starting graceful shutdown...`);
  nonceStore.startDraining();

  server.close(() => {
    console.log('All connections closed. Exiting.');
    process.exit(0);
  });

  // Force exit after 30 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 30000);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = { app, server, nonceStore };
